#include "ksStateManualEditTask.h"
#include <vector>
#include <tuple>
#include <utility>
#include <iostream>
#include <stdexcept>
using T=ks::StateManualEditTask;using W=T::Write;using C=T::Child;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;auto verify=[&](unsigned type,unsigned incoming,unsigned cached,unsigned input,unsigned pickup,unsigned storePolicy,unsigned midiPolicy,unsigned control,unsigned part,uint32_t field,bool overrideBefore,bool overrideAfter){const uint32_t base=0xffa30000;T task(base+field,uint8_t(incoming));const unsigned storeClocks=(type+incoming)&3;const unsigned packed=uint8_t(incoming*13+17);const uint32_t packedField=field^0x12345678;const bool pack=type>=1&&type<=6;std::vector<std::pair<W,unsigned>> writes;using Event=std::tuple<C,unsigned,unsigned>;std::vector<Event> children;unsigned reads=0,clocks=0,steps=0;
 auto read=[&](T::Read r)->uint32_t{++reads;switch(r){case T::Read::Override:return overrideBefore?base:0;case T::Read::Current:return base;case T::Read::Type:check(task.field()==field,"Initial logical index differs");return type;case T::Read::LiveBase:return 0xffa33001;case T::Read::Cached:check(task.field()==(pack?packedField:field),"Packed logical index differs");return cached;case T::Read::Input:return input;case T::Read::Pickup:return pickup;case T::Read::StorePolicy:return storePolicy;case T::Read::WriteOverride:return overrideAfter?0xffa35000:0;case T::Read::WriteCurrent:return 0xffa36000;case T::Read::MidiPolicy:return midiPolicy;case T::Read::MidiControl:return control;case T::Read::Part:return part;}return 0;};auto write=[&](W w,uint8_t value){writes.emplace_back(w,value);};while(!task.awaitingPost()){check(++steps<256,"Manual job stalled");if(task.awaitingChild()){const auto c=task.child();if(c==C::PackedFields){check(task.packedGroup()==type&&task.value()==incoming,"Packing request differs");children.emplace_back(c,type,incoming);check(task.resumeChild(packed,packedField),"Pack result rejected");}else{children.emplace_back(c,c==C::Dirty?0:task.midiControl(),c==C::Dirty?0:task.midiValue());check(task.resumeChild(),"Manual child rejected");}continue;}const auto cost=task.nextClocks(storeClocks),before=reads;const auto stores=writes.size();check(cost>0,"Manual premature complete");check(!task.advanceBefore(cost-1,read,write,storeClocks)&&reads==before&&writes.size()==stores,"Manual early observation");check(task.advanceBefore(cost,read,write,storeClocks)==cost,"Manual admission differs");clocks+=cost;}
 std::vector<std::pair<W,unsigned>> expectedWrites;std::vector<Event> expectedChildren;const unsigned value=pack?packed:incoming;unsigned prior=cached;bool blocked=false;if(pack){expectedWrites.emplace_back(W::Input,incoming);expectedChildren.emplace_back(C::PackedFields,type,incoming);}
 if(!type&&pickup){if(prior==255&&value!=input){prior=value>input?254:253;expectedWrites.emplace_back(W::Marker,prior);}if(prior==254&&value>uint8_t(input+1))blocked=true;if(prior==253&&value<uint8_t(input-1))blocked=true;}
 if(!blocked&&value!=prior){expectedWrites.emplace_back(W::Cached,value);if(type==127||type==254||storePolicy>=63)expectedWrites.emplace_back(W::Preset,value);if(type<128&&midiPolicy!=63){if(control>=128){expectedChildren.emplace_back(C::MidiHigh,62,control&127);expectedChildren.emplace_back(C::Midi,6,value);}else expectedChildren.emplace_back(C::Midi,control,value);}expectedWrites.emplace_back(W::Part,part);expectedChildren.emplace_back(C::Dirty,0,0);}
 expectedWrites.emplace_back(W::Edited,1);if(writes!=expectedWrites||children!=expectedChildren){std::cerr<<"type="<<type<<" value="<<incoming<<" cached="<<cached<<" input="<<input<<" pickup="<<pickup<<" writes="<<writes.size()<<" expected="<<expectedWrites.size()<<" children="<<children.size()<<" expected="<<expectedChildren.size()<<'\n';throw std::runtime_error("Manual pickup/cache/preset/MIDI semantics differ");}
 check(task.field()==(pack?packedField:field)&&task.value()==value&&!task.complete()&&!task.nextClocks(storeClocks),"Manual terminal context differs");check(!task.advanceBefore(999,read,write,storeClocks)&&task.retirePost()&&task.complete()&&!task.retirePost()&&!task.resumeChild(),"Manual zero-clock post retirement differs");check(clocks>100&&clocks<1000,"Manual bounded schedule differs");++cases;};
 for(unsigned type=0;type<256;++type)for(unsigned value=0;value<256;++value)for(unsigned cached:{0u,253u,254u,255u})for(unsigned pickup:{0u,1u})verify(type,value,cached,(value*17+type*23)&255,pickup,(value+type)&255,(value*13+type*17)&255,(value*19+type*23)&255,(type+value)&255,0x12340000+type,value&1,type&1);
 for(unsigned input=0;input<256;++input)for(unsigned value=0;value<256;++value)for(unsigned cached:{253u,254u,255u})verify(0,value,cached,input,255,64,0,input,value,0xffffff00+input,input&1,value&1);
 for(unsigned control=0;control<256;++control)for(unsigned policy=0;policy<256;++policy)for(unsigned type:{0u,1u,6u,7u,127u,128u,254u,255u})verify(type,127,0,127,0,policy,policy,control,control,control^0xdeadbeef,control&1,policy&1);
 std::cout<<"PASS: "<<cases<<" whole live manual edits/allbyte types/values/cache/pickup/input/MIDI/policies,independent hysteresis+packing+write+feedback model,late refs/wrap/deadlines/zero-clock post retirement\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
